import boto3

def check_corpus_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': text
            }
        ]
    )
    toxic_content_detected = any(result['Toxicity'] > 0.5 for result in response['Results'])
    return not toxic_content_detected

from typing import Any, Dict, List


class EmbeddingRequest:
    def __init__(self, text: str, model: str):
        self.text = text
        self.model = model

    def to_dict(self) -> Dict[str, Any]:
        return {
            'text': self.text,
            'model': self.model
        }


class EmbeddingResponse:
    def __init__(self, embedding: List[float]):
        self.embedding = embedding

    @classmethod
    def from_dict(cls, data: Dict[str, Any]):
        return cls(embedding=data['embedding'])


def normalize_embedding(embedding: List[float]) -> List[float]:
    import numpy as np
    embedding_array = np.array(embedding)
    norm = np.linalg.norm(embedding_array)
    if norm == 0:
        return embedding
    return embedding_array / norm


def denormalize_embedding(normalized_embedding: List[float], original_norm: float) -> List[float]:
    import numpy as np
    normalized_array = np.array(normalized_embedding)
    return (normalized_array * original_norm).tolist()

import os
from openai import AzureOpenAI

class EmbeddingsClient:
    def __init__(self):
        self.client = AzureOpenAI(
            api_key=os.getenv('AZURE_OPENAI_API_KEY'),
            api_version='2023-05-15',
            azure_endpoint=os.getenv('AZURE_OPENAI_ENDPOINT')
        )

    def get_embedding(self, text):
        response = self.client.embeddings.create(
            input=text,
            model='text-embedding-ada-002'
        )
        return response.data[0].embedding

import boto3

def embed_for_search(query, documents):
    bedrock = boto3.client('bedrock-runtime')
    model_id = 'amazon.titan-embed-text-v1'

    query_embedding = bedrock.invoke_model(
        modelId=model_id,
        body={
            'inputText': query
        }
    )
    document_embeddings = []
    for doc in documents:
        doc_embedding = bedrock.invoke_model(
            modelId=model_id,
            body={
                'inputText': doc
            }
        )
        document_embeddings.append(doc_embedding)
    return query_embedding, document_embeddings

import boto3

bedrock = boto3.client('bedrock-runtime')

def generate_embeddings(texts):
    model_id = 'amazon.titan-embed-text-v1'
    embeddings = []
    for text in texts:
        response = bedrock.invoke_model(
            modelId=model_id,
            body={
                'inputText': text
            }
        )
        embedding = response['embedding']
        embeddings.append(embedding)
    return embeddings
